    return s == s[::-1]

def compute_palindrome_degree(s):
    n = len(s)
    if n == 0:
        return 0
    if not is_palindrome(s):
        return 0
    if n == 1:
        return 1
    k = 1
    while True:
        m = n - k
        if m <= 0:
            break
